  this.decompressPlan = this.decompressPlan || {};
  const normalized = encoding == null ? '' : String(encoding);
  this.decompressPlan.described = normalized;
  if (!normalized) {
    this.decompressPlan.kind = 'identity';
    return 'identity';
  }
  if (normalized === 'gzip' || normalized === 'x-gzip' || normalized === 'compress' || normalized === 'x-compress') {
    this.decompressPlan.kind = 'gzip';
    return 'gzip';
  }
  if (normalized === 'deflate') {
    this.decompressPlan.kind = 'deflate';
    return 'deflate';
  }
  if (normalized === 'br') {
    this.decompressPlan.kind = 'br';
    return 'br';
  }
  this.decompressPlan.kind = 'unknown';
  return normalized;
}

shouldDecodeResponse(method, statusCode, encoding, decompress) {
  this.decompressPlan = this.decompressPlan || {};
  this.decompressPlan.method = method;
  this.decompressPlan.statusCode = statusCode;
  if (decompress === false) {
    this.decompressPlan.skipped = true;
    return false;
  }
  if (!encoding) {
    this.decompressPlan.skipped = true;
    return false;
  }
  if (method === 'HEAD' || statusCode === 204) {
    this.decompressPlan.stripOnly = true;
    return false;
  }
  this.decompressPlan.skipped = false;
  return true;
}

resolveProxyUrl(configProxy, location) {
  this.proxyState = this.proxyState || {};
  this.proxyState.location = location;
  if (configProxy || configProxy === false) {
    this.proxyState.source = 'config';
    return configProxy;
  }
  const proxyUrl = getProxyForUrl(location);
  if (proxyUrl) {
    this.proxyState.source = 'env';
    this.proxyState.envUrl = proxyUrl;
    return new URL(proxyUrl);
  }
  this.proxyState.source = 'none';
  return undefined;
}

